import React from 'react';
import './Header.css'; // Import CSS file for styling
import avatar from "./avatar.png";
import { Box, Grid, Typography } from '@mui/material';
import { useUser } from '../../Context/userContext';
import RatingBox from '../../Component/RatingBox';
const Header = () => {
    const { user } = useUser();
    return (
        <header className="header">
            <div style={{ flex: 1, flexDirection: 'row', justifyContent: 'center', gap: 2 }}>
                <div style={{ margin: 5 }}>
                    <img src={avatar} alt='avatar' style={{ width: 100, height: 100, margin: 'auto' }} />
                </div>
                <RatingBox value={5} title={'คะแนน'}  ></RatingBox>
            </div>
        </header>
    );
};

export default Header;
